-- 560: Original BrillaPrep WASSCE Social Studies sprint 3 beta questions, part 7 of 15 (batch wassce-social-studies-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_560_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_560_guard;
INSERT INTO _migration_560_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_025' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_mig' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The official count of all the people living in a country at a particular time is called...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A population census","B. A voter register","C. An opinion poll","D. A sample survey"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A population census enumerates every person in the country, recording numbers, age, sex and housing conditions. A voter register lists only eligible voters, and opinion polls and sample surveys collect data from small selected groups rather than the whole population. Therefore the correct answer is A: A population census.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_025' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_560_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_026' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_mig' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Ghana aims to conduct a national population and housing census approximately every...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Two years","B. Ten years","C. Five years","D. Twenty years"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Ghana’s censuses — 1960, 1970, 1984, 2000, 2010 and 2021 — follow the international decennial (ten-year) standard recommended by the United Nations. Two- and five-year intervals would be prohibitively expensive, and twenty years would leave planners with badly outdated data. Therefore the correct answer is B: Ten years.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_026' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_560_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_027' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_mig' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The movement of people from the countryside to settle permanently in towns and cities is known as...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Emigration","B. Immigration","C. Rural-urban migration","D. Transhumance"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Rural-urban migration is internal movement from villages to urban centres within the same country. Emigration and immigration cross international borders (leaving and entering a country respectively), and transhumance is the seasonal movement of livestock herders in search of pasture. Therefore the correct answer is C: Rural-urban migration.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_027' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_560_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_028' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_mig' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A Ghanaian who leaves Ghana to settle permanently in another country is described in Ghana as...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. An immigrant","B. A refugee","C. A commuter","D. An emigrant"]' AND q.correct_answer IS 'D' AND q.explanation IS 'An emigrant exits (e-) his or her home country to live abroad; the same person is an immigrant (im-) to the receiving country. A refugee flees persecution or war — a specific legal status, not every migrant — and a commuter travels daily between home and work without relocating. Therefore the correct answer is D: An emigrant.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_028' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_025', 'topic_wassce_p2_soc_mig', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'The official count of all the people living in a country at a particular time is called...', 'multiple_choice', NULL, '["A. A population census","B. A voter register","C. An opinion poll","D. A sample survey"]', 'A', 'A population census enumerates every person in the country, recording numbers, age, sex and housing conditions. A voter register lists only eligible voters, and opinion polls and sample surveys collect data from small selected groups rather than the whole population. Therefore the correct answer is A: A population census.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec');
