INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_028', 'topic_wassce_p2_soc_mig', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'A Ghanaian who leaves Ghana to settle permanently in another country is described in Ghana as...', 'multiple_choice', NULL, '["A. An immigrant","B. A refugee","C. A commuter","D. An emigrant"]', 'D', 'An emigrant exits (e-) his or her home country to live abroad; the same person is an immigrant (im-) to the receiving country. A refugee flees persecution or war — a specific legal status, not every migrant — and a commuter travels daily between home and work without relocating. Therefore the correct answer is D: An emigrant.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec');
